<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter, RouterLink } from 'vue-router'
import CodeEditor from '@/components/CodeEditor.vue'
import { courseApi, codeApi, type CodeRuntime, type CodeRunResult } from '@/api'
import { errMsg } from '@/api/http'

const route=useRoute(),router=useRouter(),lesson=ref<any>(null),snippets=ref<any[]>([]),selectedId=ref<number|null>(null),code=ref(''),stdin=ref(''),runtime=ref<CodeRuntime|null>(null),result=ref<CodeRunResult|null>(null),running=ref(false),error=ref('')
const selected=computed(()=>snippets.value.find(s=>s.id===selectedId.value)||null)
function select(s:any){selectedId.value=s.id;code.value=s.code||'';stdin.value=s.stdin||'';result.value=null;void router.replace({name:'lesson-lab',params:{slug:route.params.slug},query:{snippet:String(s.id)}})}
async function load(){error.value='';try{const r=await courseApi.lesson(route.params.slug as string);lesson.value=r.lesson||r;snippets.value=r.snippets||[];runtime.value=await codeApi.runtime().catch(()=>null);if(!snippets.value.length){error.value='这节课没有可用的代码示例。';return}const id=Number(route.query.snippet);select(snippets.value.find(s=>s.id===id)||snippets.value[0])}catch(e){error.value=errMsg(e)}}
async function run(){if(!runtime.value?.ready||running.value)return;running.value=true;result.value=null;try{result.value=await codeApi.run(code.value,stdin.value)}catch(e){error.value=errMsg(e)}finally{running.value=false}}
watch(()=>route.params.slug,()=>void load());onMounted(()=>void load())
</script>
<template><div class="container lab-page"><div class="lab-top"><div><RouterLink :to="`/lesson/${route.params.slug}?tab=notes`">← 返回笔记</RouterLink><h1>{{lesson?.title||'代码实验室'}}</h1><p>独立编辑与运行区域；修改不会覆盖原始课程示例。</p></div><span class="badge badge--mint">代码实验室</span></div>
 <p v-if="error" class="card lab-error">{{error}}</p><div v-else class="lab-layout"><aside class="card lab-list"><h2>示例单元</h2><button v-for="s in snippets" :key="s.id" :class="{active:s.id===selectedId}" @click="select(s)"><b>{{s.title}}</b><small>{{s.language||'java'}}</small></button></aside><section class="card lab-editor"><div v-if="selected" class="editor-head"><div><span class="badge badge--lilac">{{selected.language||'java'}}</span><b>{{selected.title}}</b></div><button class="btn btn--primary" :disabled="!runtime?.ready||running" @click="run">{{running?'运行中…':'▶ 运行代码'}}</button></div><p v-if="runtime&&!runtime.ready" class="warn">{{runtime.note}}</p><p v-else-if="!runtime" class="warn">暂时无法连接代码执行环境。</p><p v-if="selected?.explanation" class="explanation">{{selected.explanation}}</p><CodeEditor v-model="code" :min-rows="18" @run="run"/><label class="stdin">标准输入（可选）<textarea v-model="stdin" rows="3" /></label><div v-if="result" class="result" :class="result.success?'pass':'fail'"><b>{{result.success?'运行成功':result.message}}</b><span>{{result.durationMs}} ms</span><pre v-if="result.output||result.stdout||result.stderr">{{result.output||result.stdout||result.stderr}}</pre></div></section></div>
 <section class="card lab-exercises"><h2>课后习题</h2><p>习题单独放在练习区，不与示例编辑器混在一起。</p><RouterLink class="btn btn--ghost" to="/exercises">前往代码练习 →</RouterLink></section></div></template>
<style scoped>.lab-page{padding:28px 0}.lab-top{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}.lab-top h1{margin:8px 0}.lab-top p,.lab-exercises p{color:var(--c-ink-soft)}.lab-top a{color:var(--c-mint)}.lab-layout{display:grid;grid-template-columns:250px minmax(0,1fr);gap:18px;align-items:start}.lab-list,.lab-editor,.lab-exercises{padding:20px}.lab-list{display:flex;flex-direction:column;gap:8px}.lab-list h2,.lab-exercises h2{margin:0 0 8px}.lab-list button{text-align:left;padding:12px;border:1px solid var(--c-line);border-radius:12px;background:var(--c-paper);color:var(--c-ink);cursor:pointer;display:flex;flex-direction:column;gap:4px}.lab-list button.active{background:var(--c-mint);color:#fff}.lab-list small{opacity:.75}.editor-head{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:14px}.editor-head>div{display:flex;align-items:center;gap:10px}.warn{padding:10px;background:#fff2d6;border-radius:10px;color:#745619}.explanation{line-height:1.7}.stdin{display:block;margin-top:14px;font-weight:700}.stdin textarea{display:block;width:100%;margin-top:6px;padding:10px;border:1px solid var(--c-line);border-radius:10px;background:var(--c-paper);color:var(--c-ink);font:inherit}.result{margin-top:14px;padding:12px;border-radius:10px}.result.pass{background:#e8f8ef;color:#146543}.result.fail{background:#fff0ee;color:#8f3129}.result span{float:right}.result pre{white-space:pre-wrap;overflow:auto}.lab-exercises{margin-top:18px}.lab-error{padding:20px}@media(max-width:800px){.lab-layout{grid-template-columns:1fr}.lab-list{display:grid;grid-template-columns:1fr 1fr}.lab-list h2{grid-column:1/-1}.editor-head{align-items:flex-start;flex-direction:column}}</style>
